// the query.js doneInsert shape with the emit calls and an emitter base class
class Emitter {
  constructor() {
    this.handlers = [];
  }
  emit(name, value) {
    this.handlers.push(name + ':' + String(value));
    return true;
  }
}
class Command extends Emitter {
  constructor() {
    super();
    this.next = null;
  }
}
class Query extends Command {
  constructor(err) {
    super();
    this.err = err;
    this.rows = [];
    this.fields = [];
    this.resultIndex = 0;
    this.localStreamError = null;
    this.onResult = null;
  }
  doneInsert(rs) {
    if (this.err) {
      if (this.onResult) {
        this.onResult(this.err, rs);
      } else {
        this.emit('error', this.err);
      }
      return null;
    }
    this.rows.push(rs);
    this.fields.push(void 0);
    this.emit('fields', void 0);
    this.emit('result', rs);
    if (rs.serverStatus & 8) {
      this.resultIndex++;
      return 'more';
    }
    return 'done';
  }
  fromHeader(h) {
    return this.doneInsert(h);
  }
  fail() {
    return this.doneInsert(null);
  }
}
module.exports = { Query };
